        "countries": [],
        "label": "Source posting evidence",
        "sourceName": "Cloudflare",
        "url": "https://boards.greenhouse.io/cloudflare/jobs/8331153?gh_jid=8331153",
        "capturedAt": "2026-11-03T11:56:03.728Z",
